create table if not exists public.app_integrations(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text not null default '',endpoint text not null default '',secret text not null default '',active boolean not null default true,settings jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.app_integrations enable row level security;